function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.inventory}</svg>`;}
const storageKey='zentro-pos-demo-v1';let storageOK=true,loadMessage='';
function loadState(){try{const raw=localStorage.getItem(storageKey);if(!raw)return createSeed();if(raw.length>5000000)throw Error('Oversized demo data');const s=JSON.parse(raw);if(s.schemaVersion!==1||!['companies','products','sales','customers','users','audit','licenses','stockMoves','purchases','expenses','heldCarts'].every(k=>Array.isArray(s[k])&&s[k].length<=30000)||!s.settings||!s.companies.length)throw Error('Invalid demo data');return s;}catch{loadMessage='Saved demo data was unavailable or invalid. A fresh sample workspace is open.';return createSeed();}}
let state=loadState();
const ui={route:'dashboard',role:'admin',companyId:state.companies[0].id,search:'',category:'All products',filter:'all',cart:[],discountBps:0,method:'cash',customerId:'',cash:'',dialog:null,confirm:null,selected:new Set(),dateStart:'',dateEnd:'',period:7,txId:makeId(),mobile:false};
function makeId(){return globalThis.crypto?.randomUUID?.()||`local-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function ctx(){return{role:ui.role,companyId:ui.companyId,user:ui.role==='cashier'?'Ali Hassan':ui.role==='inventory'?'Sara Ahmed':'Sajjad Haider'};}
function company(){return state.companies.find(c=>c.id===ui.companyId)||state.companies[0];}
function settings(){return state.settings[ui.companyId]||{name:company().name,currency:'PKR',taxBps:0,address:'',phone:'',receiptNote:'Thank you!'};}
function rows(name){return scope(state[name]||[],ui.companyId);}
function money(n,plain=false){const value=new Intl.NumberFormat('en-PK',{minimumFractionDigits:0,maximumFractionDigits:2}).format((Number(n)||0)/100);return plain?value:`Rs. ${value}`;}
function amountInput(n){return((Number(n)||0)/100).toFixed(2);}
function initials(name){return String(name).split(/\s+/).slice(0,2).map(p=>p[0]||'').join('').toUpperCase();}
function categoryClass(c){return({'Personal care':'personal-care','Home & living':'home-living','Electronics':'electronics','Accessories':'accessories','Groceries':'groceries','Stationery':'stationery'})[c]||'personal-care';}
function productArt(p,large=false){return `<div class="${large?'product-art':'product-thumb'} ${categoryClass(p.category)}">${icon(p.art||'box',large?64:26)}</div>`;}
function dateKey(d){const n=new Date(d);return`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;}
function shortDate(d){return new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short'});}
function dateTime(d){return new Date(d).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}
function badge(text,type='success'){return`<span class="badge ${type}"><span class="badge-dot"></span>${e(text)}</span>`;}
function button(text,action,kind='primary',extra=''){return`<button type="button" class="btn ${kind==='primary'?'btn-primary':kind==='danger'?'btn-danger':''}" data-action="${e(action)}" ${extra}>${text}</button>`;}
function empty(title,detail='',action=''){return`<div class="empty-state">${icon('inventory',38)}<h3>${e(title)}</h3><p>${e(detail)}</p>${action}</div>`;}
function save(next){state=next;try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}render();}
function mutate(fn){const next=structuredClone(state);fn(next);save(next);}
function audit(next,action,detail,platform=false){next.audit.unshift({id:makeId(),companyId:platform?'platform':ui.companyId,user:ctx().user,action,detail,createdAt:new Date().toISOString()});}
function nav(route){if(!can(ui.role,route)){toast('This screen is not available for the selected role.','error');return;}ui.route=route;ui.search='';ui.filter='all';ui.category='All products';ui.mobile=false;render();window.scrollTo({top:0,behavior:'instant'});}
function resetCart(){ui.cart=[];ui.discountBps=0;ui.customerId='';ui.cash='';ui.txId=makeId();}
function switchRole(role){if(!ROLES[role])return;resetCart();ui.role=role;ui.route=ROLES[role][0];ui.search='';ui.filter='all';render();}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.setAttribute('role',type==='error'?'alert':'status');el.innerHTML=icon(type==='error'?'info':'check')+`<span>${e(message)}</span>`;document.getElementById('toasts').append(el);setTimeout(()=>el.remove(),5500);}
function getCalc(){return calculateCart(ui.cart,state.products,ui.companyId,ui.discountBps,settings().taxBps||0);}
function selectedSales(){return rows('sales').filter(s=>(!ui.dateStart||dateKey(s.createdAt)>=ui.dateStart)&&(!ui.dateEnd||dateKey(s.createdAt)<=ui.dateEnd));}
function currentSales(){return selectedSales().filter(s=>s.status==='completed');}
function sums(sales){return sales.reduce((a,s)=>({total:a.total+s.total,cost:a.cost+s.cost,profit:a.profit+s.grossProfit,tax:a.tax+s.tax,discount:a.discount+s.discount,count:a.count+1}),{total:0,cost:0,profit:0,tax:0,discount:0,count:0});}
function pageHead(title,subtitle,actions='',eyebrow='WORKSPACE'){return`<div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p class="subtitle">${e(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,note,ic='wallet',color='',detail=''){return`<article class="stat-card"><div class="stat-top"><span>${e(label)}</span><span class="stat-icon ${color}">${icon(ic,17)}</span></div><div class="stat-value num">${value}</div><div class="stat-foot">${detail?`<strong>${e(detail)}</strong>`:''}<span>${e(note)}</span></div><svg class="mini-spark" viewBox="0 0 75 30" aria-hidden="true"><path d="M2 24 12 20 20 23 30 11 39 15 50 8 60 10 73 2" fill="none" stroke="${color==='green'?'#5ebf9f':color==='amber'?'#d7ae68':color==='blue'?'#8da9d6':'#a18cdd'}" stroke-width="1.8"/></svg></article>`;}
function searchField(placeholder='Search products, SKU or barcode…'){return`<div class="search-field ${ui.route==='pos'?'pos-search':''}">${icon('search',16)}<input id="page-search" name="page-search" type="search" maxlength="120" autocomplete="off" value="${e(ui.search)}" placeholder="${e(placeholder)}" aria-label="${e(placeholder)}"></div>`;}
function footer(){return`<footer class="app-footer"><span><span class="foot-brand">Zentro - POS</span><span class="footer-dot">·</span>Your business, beautifully organized.</span><a href="mailto:sajjadhaiderconnect@gmail.com">Developed By Sajjad Haider</a></footer>`;}
function render(){const isMobile=window.matchMedia('(max-width:700px)').matches;const active=document.activeElement,focusId=active?.id,selection=active?.selectionStart;const navGroup=(label,list)=>`<div class="nav-group"><div class="nav-label">${label}</div>${list.filter(r=>can(ui.role,r)).map(r=>`<button type="button" class="nav-link ${ui.route===r?'active':''}" data-route="${r}" ${ui.route===r?'aria-current="page"':''}>${icon(r)}<span>${paths[r]}</span>${r==='pos'?'<span class="nav-badge">F2</span>':''}</button>`).join('')}</div>`;
 const main=views[ui.route]||dashboard;
 document.getElementById('app').innerHTML=`<a class="a11y-skip" href="#main-content">Skip to content</a><div class="offcanvas-backdrop ${ui.mobile?'visible':''}" data-action="mobile-close"></div><div class="app-shell"><aside class="sidebar ${ui.mobile?'open':''}" aria-label="Main navigation" ${isMobile&&!ui.mobile?'inert aria-hidden="true"':''}><div class="brand"><div class="brand-mark">z</div><div class="brand-word">zentro<span class="brand-dot">.</span><small>POINT OF SALE</small></div><button type="button" class="mobile-close" data-action="mobile-close" aria-label="Close navigation">${icon('close')}</button></div><div class="workspace-switch"><div class="workspace-logo">${e(initials(company().name))}</div><div><select id="company-switch" aria-label="Switch fictional demo company">${state.companies.map(c=>`<option value="${e(c.id)}" ${c.id===ui.companyId?'selected':''}>${e(c.name)}</option>`).join('')}</select><small>${ui.role==='power'?'PLATFORM DEMO':'MAIN BRANCH · DEMO'}</small></div></div><nav class="sidebar-nav">${ui.role==='power'?navGroup('PLATFORM',['power','settings']):navGroup('WORKSPACE',['dashboard','pos','inventory','customers','sales','purchases'])+navGroup('MANAGEMENT',['reports','team','barcodes','audit','settings'])}</nav><div class="sidebar-bottom"><button type="button" class="power-shortcut" data-action="${ui.role==='power'?'admin-demo':'power-demo'}">${icon(ui.role==='power'?'inventory':'power',20)}<span>${ui.role==='power'?'Company workspace':'Power console'}<small>${ui.role==='power'?'Return to admin demo':'Companies & licensing demo'}</small></span>${icon('chevron',13)}</button><div class="sidebar-version"><span>LOCAL EVALUATION KIT</span><span>v0.1.0</span></div></div></aside><div class="main-shell" ${isMobile&&ui.mobile?'inert':''}><header class="topbar"><div class="breadcrumb"><button type="button" class="icon-button mobile-menu" data-action="mobile-open" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevron',12)}<strong>${paths[ui.route]||'Overview'}</strong></div><div class="top-actions"><span class="top-status"><span class="dot"></span>Saved on this browser</span><button type="button" class="icon-button" data-action="help" aria-label="Help and app information">${icon('help',17)}</button><button type="button" class="icon-button" data-action="alerts" aria-label="Stock alerts">${icon('bell',17)}</button><div class="profile"><span class="avatar">${e(initials(ctx().user))}</span><div><select id="role-switch" aria-label="Switch demo role">${Object.keys(ROLES).map(r=>`<option value="${r}" ${r===ui.role?'selected':''}>${ROLE_NAMES[r]}</option>`).join('')}</select><small>Demo role · no real login</small></div></div></div></header><div class="demo-strip"><span><span class="demo-pill">DEMO</span>Fictional sample data. Backend, authentication and cloud sync are not connected.</span><button type="button" data-action="activation">Try activation flow ${icon('arrow',12)}</button></div>${!storageOK?'<div class="storage-warning">Browser storage is unavailable. Changes last only until this page is closed.</div>':''}<main class="content" id="main-content" tabindex="-1">${main()}${footer()}</main></div></div>`;
 if(focusId){const restored=document.getElementById(focusId);if(restored){restored.focus({preventScroll:true});if(typeof selection==='number'&&typeof restored.setSelectionRange==='function')try{restored.setSelectionRange(selection,selection);}catch{}}}
}
function salesTable(sales,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th>${compact?'':'<th>Date & time</th>'}<th>Amount</th><th>Payment</th><th>Status</th><th class="text-right">${compact?'':'Actions'}</th></tr></thead><tbody>${sales.length?sales.map(s=>{const c=rows('customers').find(c=>c.id===s.customerId);return`<tr><td><strong class="table-id">${e(s.number)}</strong></td><td>${e(c?.name||'Walk-in customer')}</td>${compact?'':`<td>${e(dateTime(s.createdAt))}<div class="tag-line">${e(s.user)}</div></td>`}<td><strong>${money(s.total)}</strong></td><td>${e(s.method.charAt(0).toUpperCase()+s.method.slice(1))}</td><td>${badge(s.status==='refunded'?'Refunded':'Completed',s.status==='refunded'?'danger':'success')}</td><td><div class="row-actions"><button type="button" data-action="receipt" data-id="${e(s.id)}" aria-label="View receipt ${e(s.number)}">${icon('eye',13)}</button></div></td></tr>`;}).join(''):'<tr><td colspan="7" class="table-empty">No sales found for this view.</td></tr>'}</tbody></table></div>`;}
function chart(days=7){const today=new Date(),points=[];for(let i=days-1;i>=0;i--){const d=new Date(today);d.setDate(d.getDate()-i);const key=dateKey(d),total=rows('sales').filter(s=>s.status==='completed'&&dateKey(s.createdAt)===key).reduce((a,s)=>a+s.total,0);points.push({date:d,total});}
 const max=Math.max(...points.map(p=>p.total),10000)*1.2,w=590,h=155,left=47,right=12,top=16,bottom=28;const x=i=>left+i*(w-left-right)/Math.max(points.length-1,1),y=n=>top+(h-top)*(1-n/max);const poly=points.map((p,i)=>`${x(i).toFixed(1)},${y(p.total).toFixed(1)}`).join(' '),area=`M${left},${h} L${poly.replaceAll(' ',' L')} L${x(points.length-1)},${h} Z`;
 return`<svg class="revenue-chart" viewBox="0 0 590 196" role="img" aria-label="Actual demo sales over the last ${days} days"><defs><linearGradient id="revenue-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#997ae7" stop-opacity=".19"/><stop offset="100%" stop-color="#997ae7" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(r=>`<line class="chart-grid" x1="${left}" x2="${w-right}" y1="${y(max*r)}" y2="${y(max*r)}"/><text class="chart-axis-label" x="2" y="${y(max*r)+3}">${(max*r/100000).toFixed(0)}k</text>`).join('')}<path d="${area}" fill="url(#revenue-fill)"/><polyline class="chart-paid" points="${poly}"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.total)}" r="3.1" fill="white" stroke="#8969da" stroke-width="1.7"><title>${shortDate(p.date)}: ${money(p.total)}</title></circle>${days<=7||i%3===0?`<text text-anchor="middle" class="chart-axis-label" x="${x(i)}" y="${h+bottom}">${shortDate(p.date)}</text>`:''}`).join('')}</svg>`;
}
function dashboard(){const today=dateKey(new Date()),todays=rows('sales').filter(s=>s.status==='completed'&&dateKey(s.createdAt)===today),sum=sums(todays),low=rows('products').filter(p=>p.active&&p.stock<=p.low).sort((a,b)=>a.stock-b.stock),periodStart=new Date();periodStart.setDate(periodStart.getDate()-(ui.period-1));const weekTotal=rows('sales').filter(s=>s.status==='completed'&&dateKey(s.createdAt)>=dateKey(periodStart)).reduce((a,s)=>a+s.total,0);
 const best=new Map();rows('sales').filter(s=>s.status==='completed').forEach(s=>s.items.forEach(i=>best.set(i.productId,(best.get(i.productId)||0)+i.qty)));const bestProducts=[...best.entries()].sort((a,b)=>b[1]-a[1]).slice(0,4);
 return pageHead('A clearer view of your business.',`Welcome back, ${ctx().user.split(' ')[0]}. Here’s how your store is doing today.`,button(icon('download',14)+' Export report','export-report','secondary')+button(icon('plus',15)+' New sale','new-sale'))+
 `<section class="stats" aria-label="Today’s business metrics">${stat('Today’s revenue',`<span class="currency">Rs.</span>${money(sum.total,true)}`,'Completed sales today','wallet','',`${sum.count} orders`)}${stat('Gross profit',`<span class="currency">Rs.</span>${money(sum.profit,true)}`,'After product costs & discounts','up','green')}${stat('Transactions',String(sum.count),'All completed transactions','sales','blue')}${stat('Active products',String(rows('products').filter(p=>p.active).length),'Items needing attention','inventory','amber',`${low.length} low stock`)}</section>`+
 `<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Revenue overview</h2><p class="card-subtitle">A little perspective on your store’s performance</p></div><div class="chart-period"><button type="button" data-action="chart-period" data-days="7" class="${ui.period===7?'active':''}">7 days</button><button type="button" data-action="chart-period" data-days="14" class="${ui.period===14?'active':''}">14 days</button></div></div><div class="revenue-summary"><strong>${money(weekTotal)}</strong><span class="trend-pill">${icon('audit',10)} Last ${ui.period} days</span></div><div class="chart-wrap">${chart(ui.period)}</div><div class="chart-legend"><span><span class="legend-key"></span>Completed sales · PKR</span></div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Stock needs a little attention</h2><p class="card-subtitle">Keep your best sellers on the shelf</p></div><span class="alert-count">${low.length} alerts</span></div><div class="stock-list">${low.slice(0,4).map(p=>`<div class="stock-item">${productArt(p)}<div><div class="item-title">${e(p.name)}</div><div class="item-sub">${e(p.sku)}</div></div><div class="stock-right"><div class="stock-number ${p.stock===0?'danger':''}">${p.stock===0?'Out of stock':p.stock+' left'}</div><div class="stock-caption">Min. ${p.low} units</div></div></div>`).join('')||'<div class="empty-state">All stock levels look healthy.</div>'}</div><button type="button" class="card-link" data-action="low-stock">View inventory ${icon('arrow',12)}</button></section></div>`+
 `<div class="two-columns"><section class="card"><div class="table-header"><h2>Recent transactions</h2><button type="button" class="btn btn-quiet btn-small" data-route="sales">View all ${icon('arrow',12)}</button></div>${salesTable(rows('sales').slice(0,5),true)}</section><section class="card"><div class="card-head"><div><h2 class="card-title">Your best sellers</h2><p class="card-subtitle">Products your customers keep coming back for</p></div></div><div class="top-products">${bestProducts.map(([id,qty],i)=>{const p=rows('products').find(p=>p.id===id);return p?`<div class="top-product"><span class="rank">0${i+1}</span>${productArt(p)}<div><div class="item-title">${e(p.name)}</div><div class="item-sub">${e(p.category)}</div></div><span class="sold">${qty}<span class="stock-min">units sold</span></span></div>`:'';}).join('')||empty('No sales yet')}</div></section></div>`;
}
function inventory(){let products=rows('products').filter(p=>ui.filter==='archived'?!p.active:p.active);if(ui.filter==='low')products=products.filter(p=>p.stock<=p.low);const q=ui.search.toLowerCase();products=products.filter(p=>`${p.name} ${p.sku} ${p.barcode} ${p.category}`.toLowerCase().includes(q));const stockValue=rows('products').filter(p=>p.active).reduce((a,p)=>a+p.stock*p.cost,0);
 return pageHead('Everything, in its right place.','Manage your catalog, pricing and stock with confidence.',button(icon('download',14)+' Export CSV','export-inventory','secondary')+button(icon('plus',14)+' Add product','add-product'))+`<div class="stats">${stat('Catalog items',String(rows('products').filter(p=>p.active).length),'Active products','inventory')}${stat('Stock value',`<span class="currency">Rs.</span>${money(stockValue,true)}`,'Current cost × available quantity','wallet','green')}${stat('Low stock',String(rows('products').filter(p=>p.active&&p.stock>0&&p.stock<=p.low).length),'Time to restock','bell','amber')}${stat('Out of stock',String(rows('products').filter(p=>p.active&&p.stock===0).length),'Unavailable for sale','inventory','blue')}</div><div class="toolbar">${searchField()}<select id="inventory-filter" aria-label="Inventory status"><option value="all" ${ui.filter==='all'?'selected':''}>All active products</option><option value="low" ${ui.filter==='low'?'selected':''}>Low & out of stock</option><option value="archived" ${ui.filter==='archived'?'selected':''}>Archived products</option></select><span class="spacer"></span><span class="count-label">${products.length} products</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU / Barcode</th><th>Category</th>${ui.role==='cashier'?'':'<th>Cost</th>'}<th>Price</th><th>Stock</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody>${products.length?products.map(p=>`<tr><td><div class="product-cell">${productArt(p)}<div><strong>${e(p.name)}</strong><div class="tag-line">${e(p.unit)}</div></div></div></td><td><span class="table-id">${e(p.sku)}</span><div class="tag-line">${e(p.barcode)}</div></td><td>${e(p.category)}</td><td>${money(p.cost)}</td><td><strong>${money(p.price)}</strong></td><td>${p.stock}<span class="stock-min">Min. ${p.low}</span></td><td>${!p.active?badge('Archived','gray'):p.stock===0?badge('Out of stock','danger'):p.stock<=p.low?badge('Low stock','warning'):badge('In stock')}</td><td><div class="row-actions"><button type="button" data-action="stock" data-id="${e(p.id)}" aria-label="Adjust stock for ${e(p.name)}">${icon('inventory')}</button><button type="button" data-action="edit-product" data-id="${e(p.id)}" aria-label="Edit ${e(p.name)}">${icon('edit')}</button><button type="button" data-action="archive-product" data-id="${e(p.id)}" aria-label="${p.active?'Archive':'Restore'} ${e(p.name)}">${icon(p.active?'trash':'refresh')}</button></div></td></tr>`).join(''):'<tr><td colspan="8" class="table-empty">No matching products. Try a different search.</td></tr>'}</tbody></table></div></section>`;
}
function pointOfSale(){const q=ui.search.toLowerCase(),all=rows('products').filter(p=>p.active),categories=['All products',...new Set(all.map(p=>p.category))],products=all.filter(p=>(ui.category==='All products'||p.category===ui.category)&&`${p.name} ${p.sku} ${p.barcode} ${(p.barcodeAliases||[]).join(' ')}`.toLowerCase().includes(q));let calc,error='';try{calc=getCalc();}catch(err){calc={subtotal:0,discount:0,tax:0,total:0,items:[]};error=err.message;}
 return pageHead('A smooth checkout. Every time.','Scan a barcode or choose a product to start a sale.',button(icon('pause',14)+` Held carts (${rows('heldCarts').length})`,'held-carts','secondary')+`<button type="button" class="btn btn-primary mobile-cart" data-action="view-cart">${icon('purchases',14)} View cart (${ui.cart.reduce((a,l)=>a+l.qty,0)})</button>`)+
 `<div class="pos-layout"><section class="pos-product-area"><div class="toolbar">${searchField('Search or scan barcode, then press Enter…')}<span class="help-kbd">F2</span></div><div class="category-tabs" aria-label="Product categories">${categories.map(c=>`<button type="button" class="category-tab ${ui.category===c?'active':''}" data-action="category" data-category="${e(c)}">${e(c)}</button>`).join('')}</div><div class="products-grid">${products.map(p=>`<button type="button" class="product-card" data-action="add-cart" data-id="${e(p.id)}" ${!p.stock?'disabled':''} aria-label="Add ${e(p.name)} to cart">${productArt(p,true)}<span class="product-stock">${p.stock?'In stock: '+p.stock:'Out of stock'}</span><div class="product-card-name">${e(p.name)}</div><div class="product-card-category">${e(p.category)}</div><div class="product-card-bottom"><span class="product-card-price"><small>Rs.</small> ${money(p.price,true)}</span><span class="add-circle">${icon('plus',13)}</span></div></button>`).join('')||`<div class="no-results">${empty('No products found','Try a name, SKU, barcode or another category.')}</div>`}</div></section><aside class="card cart" id="current-cart" tabindex="-1" aria-label="Current sale"><div class="cart-head"><h2>Current order <span class="muted compact">(${ui.cart.reduce((a,l)=>a+l.qty,0)} items)</span></h2><button type="button" class="btn btn-quiet btn-small" data-action="clear-cart">Clear</button></div><div class="cart-body"><select class="customer-select" id="cart-customer" aria-label="Customer for this sale"><option value="">Walk-in customer</option>${rows('customers').filter(c=>c.active).map(c=>`<option value="${e(c.id)}" ${ui.customerId===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select><button type="button" class="cart-customer-button" data-action="add-customer">+ Add a customer</button><div class="cart-items">${ui.cart.length?ui.cart.map((l,i)=>{const p=rows('products').find(p=>p.id===l.productId);return`<div class="cart-item">${productArt(p)}<div class="cart-item-content"><div class="cart-item-name"><span>${e(p.name)}</span><span class="cart-item-price">${l.free?'<span class="positive">FREE</span>':money(p.price*l.qty)}</span></div><div class="cart-controls"><div class="quantity"><button type="button" data-action="cart-minus" data-index="${i}" aria-label="Reduce ${e(p.name)} quantity">−</button><span class="cart-qty-text">${l.qty}</span><button type="button" data-action="cart-plus" data-index="${i}" aria-label="Increase ${e(p.name)} quantity">+</button></div>${['admin','manager'].includes(ui.role)?`<button type="button" class="cart-free ${l.free?'active':''}" data-action="cart-free" data-index="${i}">${icon('gift',11)} ${l.free?'Free item':'Make free'}</button>`:''}<button type="button" class="cart-remove" data-action="cart-remove" data-index="${i}" aria-label="Remove ${e(p.name)}">${icon('trash',12)}</button></div></div></div>`;}).join(''):`<div class="cart-empty">${icon('purchases',34)}<p>Your next sale starts here.<br>Pick a product or scan its barcode.</p></div>`}</div><div class="cart-summary"><div class="summary-line"><span>Subtotal</span><strong>${money(calc.subtotal)}</strong></div><div class="summary-line"><span>Discount ${['admin','manager'].includes(ui.role)?`<input id="cart-discount" aria-label="Bill discount percentage" type="number" min="0" max="100" step="0.01" value="${ui.discountBps/100}"> %`:''}</span><strong>− ${money(calc.discount)}</strong></div><div class="summary-line"><span>Tax (${(settings().taxBps||0)/100}%)</span><strong>${money(calc.tax)}</strong></div></div><div class="cart-total"><span>Total payable</span><strong>${money(calc.total)}</strong></div><div class="payment-methods">${[['cash','money','Cash'],['card','card','Card'],['bank','bank','Bank'],['credit','customers','Credit']].map(([m,ic,t])=>`<button type="button" class="payment-button ${ui.method===m?'active':''}" data-action="payment-method" data-method="${m}" aria-pressed="${ui.method===m}">${icon(ic,15)}${t}</button>`).join('')}</div>${ui.method==='cash'?`<label class="cash-input" for="cash-received">Cash received <input id="cash-received" type="text" inputmode="decimal" maxlength="12" value="${e(ui.cash||amountInput(calc.total))}" aria-label="Cash received in rupees"></label>`:ui.method==='credit'?'<p class="inline-notice">A customer is required. The full total is added to their outstanding balance.</p>':'<p class="inline-notice">Records an externally processed payment. No payment gateway is connected.</p>'}<button type="button" class="btn btn-primary pay-button" data-action="checkout" ${!ui.cart.length||error?'disabled':''}>${icon('check',15)} Complete sale ${icon('arrow',15)}</button><button type="button" class="btn hold-button" data-action="hold-cart" ${!ui.cart.length?'disabled':''}>${icon('pause',13)} Hold this cart</button>${error?`<p class="cart-error">${e(error)}</p>`:''}<p class="overview-note">Free products reduce stock and retain their cost in gross profit. Whole units only in this demo.</p></div></aside></div>`;
}
function customers(){const q=ui.search.toLowerCase(),customers=rows('customers').filter(c=>c.active&&`${c.name} ${c.phone} ${c.city}`.toLowerCase().includes(q));return pageHead('Good relationships start here.','Keep customer details and purchase history in one place.',button(icon('download',14)+' Export CSV','export-customers','secondary')+button(icon('plus',14)+' Add customer','add-customer'))+`<div class="toolbar">${searchField('Search customers by name, phone or city…')}<span class="spacer"></span><span class="count-label">${customers.length} customers</span></div><div class="customer-grid">${customers.map(c=>{const purchases=rows('sales').filter(s=>s.customerId===c.id&&s.status==='completed'),spent=purchases.reduce((a,s)=>a+s.total,0);return`<article class="card customer-card"><div class="customer-top"><div class="customer-info"><span class="avatar">${e(initials(c.name))}</span><div><h3>${e(c.name)}</h3><small>${purchases.length} completed orders</small></div></div><div class="row-actions"><button type="button" data-action="edit-customer" data-id="${e(c.id)}" aria-label="Edit ${e(c.name)}">${icon('edit',13)}</button><button type="button" data-action="archive-customer" data-id="${e(c.id)}" aria-label="Archive ${e(c.name)}">${icon('trash',13)}</button></div></div><div class="customer-contact"><span>${icon('phone',13)}${e(c.phone||'No phone')}</span><span>${icon('pin',13)}${e(c.city||'No city')}</span></div><div class="customer-footer"><div>Total purchases<strong>${money(spent)}</strong></div><div class="text-right">Outstanding<strong class="${c.balance?'credit-amount':''}">${money(c.balance)}</strong></div></div><button type="button" class="btn btn-quiet btn-small full-width" data-action="customer-history" data-id="${e(c.id)}">View history ${icon('arrow',12)}</button></article>`;}).join('')||`<div class="no-results">${empty('No customers found','Add a customer or change your search.')}</div>`}</div>`;}
function sales(){const q=ui.search.toLowerCase();const sales=rows('sales').filter(s=>`${s.number} ${s.user} ${rows('customers').find(c=>c.id===s.customerId)?.name||''}`.toLowerCase().includes(q)&&(ui.filter==='all'||s.status===ui.filter));return pageHead('Every sale has a story.','Find receipts, review payments and process full returns.',button(icon('download',14)+' Export sales','export-sales','secondary')+button(icon('plus',14)+' New sale','new-sale'))+`<div class="toolbar">${searchField('Search invoice, customer or cashier…')}<select id="sales-filter" aria-label="Sale status"><option value="all">All sales</option><option value="completed" ${ui.filter==='completed'?'selected':''}>Completed</option><option value="refunded" ${ui.filter==='refunded'?'selected':''}>Refunded</option></select><span class="spacer"></span><span class="count-label">${sales.length} transactions</span></div><section class="card">${salesTable(sales)}<div class="table-note">This local demo supports full, resellable returns. Partial returns, exchanges and damaged returns are specified in the backend handoff.</div></section>`;}
function purchases(){return pageHead('Keep your shelves ready.','Receive purchased stock and keep a record of supplier deliveries.',button(icon('plus',14)+' Receive stock','add-purchase'))+`<div class="notice">${icon('info')}<span>Receiving a purchase adds stock and updates the product’s weighted average cost. Historical sale costs stay unchanged.</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Product</th><th>Supplier</th><th>Quantity</th><th>Unit cost</th><th>Total</th><th>Received</th></tr></thead><tbody>${rows('purchases').map(p=>`<tr><td><strong>${e(p.number)}</strong></td><td>${e(rows('products').find(x=>x.id===p.productId)?.name||p.productName)}</td><td>${e(p.supplier)}</td><td>${p.qty}</td><td>${money(p.cost)}</td><td><strong>${money(p.total)}</strong></td><td>${e(dateTime(p.createdAt))}</td></tr>`).join('')||'<tr><td colspan="7" class="table-empty">No purchases recorded yet. Receive stock to create your first purchase.</td></tr>'}</tbody></table></div></section>`;}
function reports(){const sales=currentSales(),sum=sums(sales),expenses=rows('expenses').filter(x=>(!ui.dateStart||dateKey(x.createdAt)>=ui.dateStart)&&(!ui.dateEnd||dateKey(x.createdAt)<=ui.dateEnd)).reduce((a,x)=>a+x.amount,0),methods=['cash','card','bank','credit'],colors=['#7654d7','#aaa0db','#d6ceee','#eee9f7'];let offset=0;const donut=methods.map((m,i)=>{const amount=sales.filter(s=>s.method===m).reduce((a,s)=>a+s.total,0),length=amount/Math.max(sum.total,1)*100;const s=`<circle cx="80" cy="80" r="58" fill="none" stroke="${colors[i]}" stroke-width="20" pathLength="100" stroke-dasharray="${length} ${100-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"/>`;offset+=length;return s;}).join('');
return pageHead('Numbers you can act on.','Understand sales, product costs and recorded operating expenses.',button(icon('plus',14)+' Add expense','add-expense','secondary')+button(icon('download',14)+' Export report','export-report'))+`<div class="toolbar"><div class="date-range">${icon('calendar',15)}<label for="date-start">From</label><input id="date-start" type="date" value="${e(ui.dateStart)}"><label for="date-end">To</label><input id="date-end" type="date" value="${e(ui.dateEnd)}"><button type="button" class="btn btn-small" data-action="clear-dates">All time</button></div></div><div class="stats">${stat('Sales collected / billed',`<span class="currency">Rs.</span>${money(sum.total,true)}`,'Including configured tax','wallet')}${stat('Gross profit',`<span class="currency">Rs.</span>${money(sum.profit,true)}`,'Excludes collected tax','up','green')}${stat('Average sale',`<span class="currency">Rs.</span>${money(sum.count?Math.round(sum.total/sum.count):0,true)}`,'Across completed orders','sales','blue')}${stat('Free product cost',`<span class="currency">Rs.</span>${money(sales.reduce((a,s)=>a+s.items.filter(i=>i.free).reduce((b,i)=>b+i.unitCost*i.qty,0),0),true)}`,'Already included in cost of goods','gift','amber')}</div><div class="report-grid"><section class="card"><div class="card-head"><h2 class="card-title">A simple profit breakdown</h2>${badge('Demo ledger','gray')}</div><div class="card-body"><div class="report-row"><span>Sales before discounts & tax</span><strong>${money(sales.reduce((a,s)=>a+s.subtotal,0))}</strong></div><div class="report-row"><span>Discounts</span><strong>− ${money(sum.discount)}</strong></div><div class="report-row"><span>Cost of goods, including free items</span><strong>− ${money(sum.cost)}</strong></div><div class="report-row"><span>Gross profit</span><strong>${money(sum.profit)}</strong></div><div class="report-row"><span>Recorded operating expenses</span><strong>− ${money(expenses)}</strong></div><div class="report-row total"><span>Operating estimate</span><strong>${money(sum.profit-expenses)}</strong></div><p class="report-sub">An operating estimate, not statutory net profit. Full refunds are excluded by original sale status; production needs dated return ledger entries.</p></div></section><section class="card"><div class="card-head"><div><h2 class="card-title">How your customers pay</h2><p class="card-subtitle">Payment mix across completed sales</p></div></div><div class="card-body donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="img" aria-label="Payment distribution"><circle cx="80" cy="80" r="58" fill="none" stroke="#f3eff8" stroke-width="20"/>${donut}<text x="80" y="77" text-anchor="middle" fill="#655b77" font-size="23" font-weight="650">${sum.count}</text><text x="80" y="95" text-anchor="middle" fill="#a798b3" font-size="9">transactions</text></svg><div class="payment-legend">${methods.map((m,i)=>`<div><svg width="7" height="7" aria-hidden="true"><rect width="7" height="7" rx="2" fill="${colors[i]}"/></svg> ${m.charAt(0).toUpperCase()+m.slice(1)}<strong>${money(sales.filter(s=>s.method===m).reduce((a,s)=>a+s.total,0))}</strong></div>`).join('')}</div></div></section></div><section class="card bottom-space brand-footer"><div class="table-header"><h2>Recorded expenses</h2></div><div class="table-wrap"><table><thead><tr><th>Description</th><th>Amount</th><th>Date</th><th>Recorded by</th></tr></thead><tbody>${rows('expenses').filter(x=>(!ui.dateStart||dateKey(x.createdAt)>=ui.dateStart)&&(!ui.dateEnd||dateKey(x.createdAt)<=ui.dateEnd)).map(x=>`<tr><td>${e(x.description)}</td><td>${money(x.amount)}</td><td>${dateTime(x.createdAt)}</td><td>${e(x.user)}</td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">No expenses in this date range.</td></tr>'}</tbody></table></div></section>`;
}
function team(){return pageHead('The right access for every role.','Create staff profiles and review the permissions each role will receive.',button(icon('plus',14)+' Add team member','add-user'))+`<div class="notice">${icon('lock')}<span>These are demo profiles. No passwords, invitations or authenticated accounts are created. The backend handoff includes secure onboarding, MFA and session controls.</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Team member</th><th>Login identifier</th><th>Role</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody>${rows('users').map(u=>`<tr><td><div class="row-user"><span class="avatar row-avatar">${e(initials(u.name))}</span><strong>${e(u.name)}</strong></div></td><td>${e(u.email)}</td><td>${badge(ROLE_NAMES[u.role]||u.role,'gray')}</td><td>${badge(u.active?'Active':'Disabled',u.active?'success':'danger')}</td><td><div class="row-actions"><button type="button" data-action="edit-user" data-id="${e(u.id)}" aria-label="Edit ${e(u.name)}">${icon('edit')}</button><button type="button" data-action="toggle-user" data-id="${e(u.id)}" aria-label="${u.active?'Disable':'Enable'} ${e(u.name)}">${icon(u.active?'lock':'refresh')}</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">No staff profiles yet.</td></tr>'}</tbody></table></div></section>`;}
function barcodeSVG(value){const {width,bars}=code39(value);return`<svg viewBox="0 0 ${width} 64" role="img" aria-label="Code 39 barcode ${e(value)}" shape-rendering="crispEdges"><rect width="${width}" height="64" fill="white"/>${bars.map(b=>`<rect x="${b.x}" y="4" width="${b.width}" height="56" fill="#222"/>`).join('')}</svg>`;}
function barcodeLabel(p){return`<div class="barcode-label"><h3>${e(p.name)}</h3><div class="label-price">${money(p.price)}</div>${barcodeSVG(p.barcode)}<div class="barcode-text">${e(p.barcode)}</div></div>`;}
function barcodes(){const q=ui.search.toLowerCase(),products=rows('products').filter(p=>p.active&&`${p.name} ${p.sku} ${p.barcode}`.toLowerCase().includes(q));return pageHead('Small labels. Big efficiency.','Generate internal Code 39 labels and keep checkout moving.',button(icon('print',14)+` Print selected (${ui.selected.size})`,'print-labels'))+`<div class="toolbar">${searchField('Search product labels…')}<button type="button" class="btn" data-action="select-labels">Select visible</button><button type="button" class="btn" data-action="clear-labels">Clear selection</button></div><div class="notice">${icon('barcodes')}<span>Internal Code 39 labels, with quiet zones. Existing manufacturer barcodes can be entered on products and scanned by a USB/Bluetooth keyboard scanner. Physical scanner and printer testing is still required.</span></div><div class="label-grid">${products.map(p=>`<article class="barcode-label"><label class="label-check"><span>${e(p.sku)}</span><input type="checkbox" class="label-checkbox" data-id="${e(p.id)}" ${ui.selected.has(p.id)?'checked':''} aria-label="Select label for ${e(p.name)}"></label><h3>${e(p.name)}</h3><div class="label-price">${money(p.price)}</div>${barcodeSVG(p.barcode)}<div class="barcode-text">${e(p.barcode)}</div></article>`).join('')||empty('No labels found')}</div>`;}
function auditView(){return pageHead('A clear record of every change.','Review local activity for the current company.',button(icon('download',14)+' Export activity','export-audit','secondary'))+`<div class="notice">${icon('info')}<span>Demo activity is editable browser data. The production backend must write protected audit events and restrict alteration.</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Action</th><th>Details</th><th>Performed by</th><th>Date & time</th></tr></thead><tbody>${rows('audit').slice(0,500).map(a=>`<tr><td><span class="activity-dot"></span><strong>${e(a.action)}</strong></td><td>${e(a.detail)}</td><td>${e(a.user)}</td><td>${e(dateTime(a.createdAt))}</td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">No activity yet.</td></tr>'}</tbody></table></div></section>`;}
function power(){return pageHead('One console. Every company.','Provision company workspaces and preview your licensing workflow.',button(icon('lock',14)+' Test activation','activation','secondary')+button(icon('plus',14)+' Create company','add-company'),'PLATFORM OWNER')+`<div class="notice amber">${icon('info')}<span><strong>Licensing preview:</strong> keys and company records here are local simulations. Secure activation, hashed key storage, device binding, expiry enforcement and revocation require the backend.</span></div><div class="stats">${stat('Companies',String(state.companies.length),'Separate demo workspaces','inventory')}${stat('Active licenses',String(state.licenses.filter(l=>l.status==='active').length),'Local demo records','lock','green')}${stat('Licensed devices',String(state.licenses.filter(l=>l.status==='active').reduce((a,l)=>a+l.devices,0)),'Simulated activations','pos','blue')}${stat('Plans available','3','Starter · Professional · Business','power','amber')}</div><div class="license-grid">${state.companies.map(c=>{const lic=state.licenses.find(l=>l.companyId===c.id&&l.status==='active');return`<article class="card company-card"><div class="company-card-head"><span class="company-logo">${e(initials(c.name))}</span>${badge(c.status==='active'?'Active':'Suspended',c.status==='active'?'success':'danger')}</div><h3>${e(c.name)}</h3><p class="owner">${e(c.owner)} · ${e(c.email)}</p><div class="company-metrics"><span>Plan<strong>${e(c.plan)}</strong></span><span>Devices<strong>${lic?.devices||0} / ${c.deviceLimit}</strong></span><span>License expiry<strong>${e(c.expires)}</strong></span></div><div class="license-key">${e(lic?.key||'No active local demo key')}</div><div class="company-actions"><button type="button" class="btn btn-small btn-primary" data-action="new-license" data-id="${e(c.id)}">${icon('plus',12)} Issue demo key</button><button type="button" class="btn btn-small" data-action="renew-company" data-id="${e(c.id)}">Renew</button><button type="button" class="btn btn-small ${c.status==='active'?'btn-danger':''}" data-action="toggle-company" data-id="${e(c.id)}">${c.status==='active'?'Suspend':'Resume'}</button></div></article>`;}).join('')}</div><section class="card brand-footer"><div class="table-header"><h2>License history</h2><span class="scope-badge">Platform only</span></div><div class="table-wrap"><table><thead><tr><th>Company</th><th>Demo key</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody>${state.licenses.map(l=>`<tr><td><strong>${e(state.companies.find(c=>c.id===l.companyId)?.name||'Unknown')}</strong></td><td class="mono">${e(l.key)}</td><td>${e(shortDate(l.createdAt))}</td><td>${badge(l.status,l.status==='active'?'success':'gray')}</td><td>${l.status==='active'?`<button type="button" class="btn btn-small btn-danger" data-action="revoke-license" data-id="${e(l.id)}">Revoke</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function settingsView(){const s=settings();return pageHead('Make Zentro feel like your store.','Manage company details, receipt preferences and your local demo.')+`<div class="settings-layout">${ui.role!=='power'?`<section class="card settings-card"><h2>Company & receipts</h2><form id="settings-form"><div class="form-grid"><div class="field full"><label for="store-name">Store name</label><input id="store-name" name="name" maxlength="80" required value="${e(s.name)}"></div><div class="field full"><label for="store-address">Address</label><input id="store-address" name="address" maxlength="160" value="${e(s.address)}"></div><div class="field"><label for="store-phone">Phone</label><input id="store-phone" name="phone" maxlength="30" value="${e(s.phone)}"></div><div class="field"><label for="store-tax">Tax percentage</label><input id="store-tax" name="tax" type="number" min="0" max="30" step="0.01" value="${(s.taxBps||0)/100}" required></div><div class="field full"><label for="receipt-note">Receipt message</label><textarea id="receipt-note" name="receiptNote" maxlength="160" required>${e(s.receiptNote)}</textarea></div></div><p class="setting-readonly">Currency: PKR · Whole-unit inventory. Tax is a configurable demo calculation, not a country-specific fiscal integration.</p><div class="form-error" id="settings-error" hidden></div><div class="settings-saving"><button type="submit" class="btn btn-primary">Save changes</button></div></form></section>`:''}<section class="card settings-card"><h2>Workspace & application</h2><div class="settings-list"><div class="setting-item"><div>Storage location<small>Fictional data stays in this browser. Never enter real customer or payment information in this demo.</small></div>${badge('Local demo','gray')}</div><div class="setting-item"><div>Cloud synchronization<small>Not connected. Your backend must provide authenticated synchronization.</small></div>${badge('Not connected','warning')}</div><div class="setting-item"><div>Security & accounts<small>Demo roles are screen previews. Production requires server-enforced authorization.</small></div>${icon('lock',20)}</div><div class="setting-item"><div>Restore sample data<small>Clears all local demo changes across every company in this browser.</small></div><button type="button" class="btn btn-small btn-danger" data-action="reset-demo">Reset demo</button></div></div><hr class="line"><div class="about-logo">zentro<span>.</span></div><p class="metric-info">Zentro - POS · Frontend evaluation kit v0.1.0</p><a class="help-email" href="mailto:sajjadhaiderconnect@gmail.com">Developed By Sajjad Haider</a><p class="settings-foot">Backend instructions, API contract and QA evidence are included in the project’s docs folder.</p></section></div>`;}
const views={dashboard,pos:pointOfSale,inventory,customers,sales,purchases,reports,team,barcodes,audit:auditView,power,settings:settingsView};

function openDialog(title,subtitle,body,large=false){const d=document.getElementById('dialog');d.className=`dialog ${large?'large':''}`;d.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${e(title)}</h2>${subtitle?`<p class="subtitle">${e(subtitle)}</p>`:''}</div><button type="button" class="dialog-close" data-action="dialog-close" aria-label="Close dialog">${icon('close',15)}</button></div><div class="dialog-body">${body}</div><div class="modal-footer-note">Zentro - POS · Local evaluation kit · Fictional data only</div>`;d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();}
function closeDialog(){document.getElementById('dialog').close();ui.dialog=null;ui.confirm=null;}
function field(label,name,value='',type='text',extra='',full=false){return`<div class="field ${full?'full':''}"><label for="field-${name}">${e(label)}</label><input id="field-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;}
function form(id,fields,label='Save changes',note=''){return`<form id="${id}">${note?`<p class="form-intro">${note}</p>`:''}<div class="form-grid">${fields}</div><div id="form-error" class="form-error" role="alert" hidden></div><div class="form-actions"><button type="button" class="btn" data-action="dialog-close">Cancel</button><button type="submit" class="btn btn-primary">${e(label)}</button></div></form>`;}
function confirmAction(title,message,fn,label='Confirm'){ui.confirm=fn;openDialog(title,'Please review before continuing.',`<p class="form-intro">${e(message)}</p><div class="form-actions"><button type="button" class="btn" data-action="dialog-close">Cancel</button><button type="button" class="btn btn-danger" data-action="confirm">${e(label)}</button></div>`);}
function productForm(id=null){permitted(ui.role,'product');const p=id?findScoped(state.products,id,ui.companyId):null;ui.dialog={type:'product',id};const categories=['Personal care','Home & living','Accessories','Electronics','Groceries','Stationery','General'];openDialog(p?'Edit product':'Add a product','Build a catalog your team can rely on.',form('product-form',field('Product name','name',p?.name||'','text','required maxlength="80"',true)+field('SKU','sku',p?.sku||`ZT-${String(rows('products').length+1).padStart(3,'0')}`,'text','required maxlength="40"')+field('Barcode / internal code','barcode',p?.barcode||`ZT${String(rows('products').length+1).padStart(5,'0')}`,'text','required maxlength="48"')+`<div class="field"><label for="field-category">Category</label><select id="field-category" name="category">${[...new Set([...categories,p?.category].filter(Boolean))].map(c=>`<option ${p?.category===c?'selected':''}>${e(c)}</option>`).join('')}</select></div>`+field('Unit','unit',p?.unit||'pcs','text','required maxlength="16"')+field('Purchase cost (Rs.)','cost',amountInput(p?.cost||0),'text','required inputmode="decimal" maxlength="12"')+field('Selling price (Rs.)','price',amountInput(p?.price||0),'text','required inputmode="decimal" maxlength="12"')+(!p?field('Opening stock','stock','0','number','required min="0" max="1000000" step="1"'):'')+field('Low-stock threshold','low',p?.low??5,'number','required min="0" max="100000" step="1"'),p?'Save product':'Create product',p?'Stock changes are recorded separately through Adjust stock or Purchases. Changing a barcode preserves the old code as a scan alias.':''));}
function customerForm(id=null){permitted(ui.role,'customer');const c=id?findScoped(state.customers,id,ui.companyId):null;ui.dialog={type:'customer',id};openDialog(c?'Edit customer':'Add a customer','A little detail makes the next visit easier.',form('customer-form',field('Full name','name',c?.name||'','text','required maxlength="80"',true)+field('Phone number','phone',c?.phone||'','tel','required maxlength="30"')+field('City','city',c?.city||'','text','maxlength="60"')+field('Email (optional)','email',c?.email||'','email','maxlength="120"',true),c?'Save customer':'Create customer'));}
function userForm(id=null){permitted(ui.role,'user');const u=id?findScoped(state.users,id,ui.companyId):null;ui.dialog={type:'user',id};openDialog(u?'Edit team member':'Add a team member','Demo staff profile — real authentication is not connected.',form('user-form',field('Full name','name',u?.name||'','text','required maxlength="80"',true)+field('Login identifier / email','email',u?.email||'','text','required maxlength="120"',true)+`<div class="field full"><label for="field-role">Role</label><select id="field-role" name="role">${['admin','manager','inventory','cashier'].map(r=>`<option value="${r}" ${u?.role===r?'selected':''}>${ROLE_NAMES[r]}</option>`).join('')}</select><small>No password is stored or generated in this frontend.</small></div>`,u?'Save profile':'Create demo profile'));}
function stockForm(id){permitted(ui.role,'stock');const p=findScoped(state.products,id,ui.companyId);ui.dialog={type:'stock',id};openDialog('Adjust stock',p.name,form('stock-form',field('Counted stock (whole units)','stock',p.stock,'number','required min="0" max="1000000" step="1"',true)+field('Reason for adjustment','reason','','text','required maxlength="160"',true),'Record adjustment',`Current stock: ${p.stock}. Every adjustment adds a stock movement and activity entry.`));}
function purchaseForm(){permitted(ui.role,'stock');ui.dialog={type:'purchase'};openDialog('Receive purchased stock','Record a delivery and update inventory.',form('purchase-form',`<div class="field full"><label for="field-productId">Product</label><select id="field-productId" name="productId">${rows('products').filter(p=>p.active).map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join('')}</select></div>`+field('Supplier','supplier','Prime Distribution (demo)','text','required maxlength="100"',true)+field('Quantity received','qty','1','number','required min="1" max="100000" step="1"')+field('Unit purchase cost (Rs.)','cost','','text','required inputmode="decimal" maxlength="12"'),'Receive stock'));}
function companyForm(){permitted(ui.role,'company');ui.dialog={type:'company'};openDialog('Create a company workspace','Your next customer starts here.',form('company-form',field('Company name','name','','text','required maxlength="80"',true)+field('Owner name','owner','','text','required maxlength="80"')+field('Owner email','email','','email','required maxlength="120"')+`<div class="field"><label for="field-plan">Plan</label><select id="field-plan" name="plan"><option>Starter</option><option selected>Professional</option><option>Business</option></select></div>`+field('Expiry date','expires','2027-10-31','date','required')+field('Allowed devices','deviceLimit','3','number','required min="1" max="100"')+field('Allowed users','userLimit','10','number','required min="1" max="1000"'),'Create company & demo key','This creates a local preview workspace. Production keys must be generated and verified by your server.'));}
function activationForm(){ui.dialog={type:'activation'};openDialog('Activate your workspace','Preview the company onboarding experience.',`<div class="activation-step"><strong>1</strong> Enter company key ${icon('arrow',12)} <strong>2</strong> Open demo workspace</div>${form('activation-form',field('Company activation key','key','','text','required maxlength="80" autocomplete="off"',true),'Preview activation','This only matches local demo keys. Secure verification, device registration and first-admin identity verification belong on the backend.')}`);}
function receipt(saleId){const sale=findScoped(state.sales,saleId,ui.companyId),s=settings(),customer=rows('customers').find(c=>c.id===sale.customerId);ui.dialog={type:'receipt',id:saleId};openDialog('Sale receipt',sale.number,`<div class="receipt"><div class="print-watermark">DEMO RECEIPT — NOT A FISCAL INVOICE</div><div class="receipt-brand"><h2>${e(s.name)}</h2><p>${e(s.address)}<br>${e(s.phone)}</p></div><div class="receipt-meta"><span>Invoice: ${e(sale.number)}</span><span>Date: ${e(dateTime(sale.createdAt))}</span><span>Cashier: ${e(sale.user)}</span><span>Customer: ${e(customer?.name||'Walk-in customer')}</span></div>${sale.status==='refunded'?'<div class="invoice-status">'+badge('Fully refunded','danger')+'</div>':''}<table><thead><tr><th>Item</th><th>Qty</th><th class="text-right">Amount</th></tr></thead><tbody>${sale.items.map(i=>`<tr><td>${e(i.name)}${i.free?' · FREE':''}</td><td>${i.qty}</td><td class="text-right">${i.free?'FREE':money(i.net)}</td></tr>`).join('')}</tbody></table><div class="modal-summary"><div class="summary-line"><span>Subtotal</span><strong>${money(sale.subtotal)}</strong></div><div class="summary-line"><span>Discount</span><strong>− ${money(sale.discount)}</strong></div><div class="summary-line"><span>Tax</span><strong>${money(sale.tax)}</strong></div><div class="cart-total"><span>Total</span><strong>${money(sale.total)}</strong></div><div class="summary-line"><span>Payment</span><strong>${e(sale.method.toUpperCase())}</strong></div>${sale.method==='cash'?`<div class="summary-line"><span>Cash received</span><strong>${money(sale.tendered)}</strong></div><div class="summary-line"><span>Change</span><strong>${money(sale.change)}</strong></div>`:''}</div>${sale.method==='credit'?'<div class="receipt-credit">Amount added to customer outstanding balance</div>':''}<div class="receipt-note">${e(s.receiptNote)}<br><span class="receipt-footer"><a href="mailto:sajjadhaiderconnect@gmail.com">Developed By Sajjad Haider</a></span></div></div><div class="form-actions no-print">${sale.status==='completed'&&['admin','manager'].includes(ui.role)?`<button type="button" class="btn btn-danger" data-action="refund" data-id="${e(sale.id)}">Full return</button>`:''}<button type="button" class="btn btn-primary" data-action="print">${icon('print',14)} Print receipt</button></div>`);}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(kind){let data,name;if(kind==='inventory'){permitted(ui.role,'product');name='inventory';data=[['SKU','Product','Barcode','Category','Stock','Unit cost (Rs.)','Price (Rs.)','Active'],...rows('products').map(p=>[p.sku,p.name,p.barcode,p.category,p.stock,amountInput(p.cost),amountInput(p.price),p.active])];}else if(kind==='customers'){permitted(ui.role,'customer');name='customers';data=[['Name','Phone','City','Outstanding (Rs.)'],...rows('customers').map(c=>[c.name,c.phone,c.city,amountInput(c.balance)])];}else if(kind==='sales'){if(!can(ui.role,'sales'))throw Error('Access denied.');name='sales';data=[['Invoice','Date','Customer','Total (Rs.)','Method','Status'],...rows('sales').map(s=>[s.number,s.createdAt,rows('customers').find(c=>c.id===s.customerId)?.name||'Walk-in',amountInput(s.total),s.method,s.status])];}else if(kind==='audit'){if(!can(ui.role,'audit'))throw Error('Access denied.');name='activity';data=[['Date','User','Action','Detail'],...rows('audit').map(a=>[a.createdAt,a.user,a.action,a.detail])];}else{if(!can(ui.role,'reports'))throw Error('Access denied.');name='report';const sum=sums(currentSales());data=[['Metric','Amount (Rs.)'],['Sales',amountInput(sum.total)],['Tax',amountInput(sum.tax)],['Discount',amountInput(sum.discount)],['Cost of goods',amountInput(sum.cost)],['Gross profit',amountInput(sum.profit)],['Completed transactions',sum.count]];}download(`zentro-${name}-${dateKey(new Date())}.csv`,toCSV(data));toast('CSV downloaded.');}

document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-route]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id,index=Number(el.dataset.index);try{if(el.dataset.route){nav(el.dataset.route);return;}switch(action){
case'mobile-open':ui.mobile=true;render();document.querySelector('.mobile-close')?.focus();break;case'mobile-close':ui.mobile=false;render();document.querySelector('.mobile-menu')?.focus();break;
case'view-cart':document.getElementById('current-cart')?.scrollIntoView({behavior:'instant',block:'start'});document.getElementById('current-cart')?.focus({preventScroll:true});break;
case'new-sale':nav('pos');document.getElementById('page-search')?.focus();break;
case'power-demo':switchRole('power');break;case'admin-demo':switchRole('admin');break;
case'chart-period':ui.period=Number(el.dataset.days)===14?14:7;render();break;
case'category':ui.category=el.dataset.category;render();break;
case'add-product':productForm();break;case'edit-product':productForm(id);break;case'add-customer':customerForm();break;case'edit-customer':customerForm(id);break;case'add-user':userForm();break;case'edit-user':userForm(id);break;case'stock':stockForm(id);break;case'add-purchase':purchaseForm();break;case'add-company':companyForm();break;case'activation':activationForm();break;
case'low-stock':if(can(ui.role,'inventory')){nav('inventory');ui.filter='low';render();}break;
case'alerts':{const low=rows('products').filter(p=>p.active&&p.stock<=p.low);openDialog('Stock alerts',`${low.length} items need attention.`,low.map(p=>`<div class="stock-item">${productArt(p)}<div><div class="item-title">${e(p.name)}</div><div class="item-sub">${p.stock} available · minimum ${p.low}</div></div></div>`).join('')||empty('All stock levels look healthy'));break;}
case'archive-product':{permitted(ui.role,'product');const p=findScoped(state.products,id,ui.companyId);confirmAction(p.active?'Archive product?':'Restore product?',p.active?`${p.name} will be removed from new sales. Its sale history remains available.`:`${p.name} will return to the active catalog.`,()=>{mutate(s=>{findScoped(s.products,id,ui.companyId).active=!p.active;audit(s,p.active?'Product archived':'Product restored',p.name);});toast('Product updated.');},p.active?'Archive product':'Restore product');break;}
case'archive-customer':{permitted(ui.role,'customer');const c=findScoped(state.customers,id,ui.companyId);if(c.balance)throw Error('Settle the outstanding balance before archiving this customer.');confirmAction('Archive customer?',`${c.name} will be hidden from new sales. Existing receipts remain available.`,()=>{mutate(s=>{findScoped(s.customers,id,ui.companyId).active=false;audit(s,'Customer archived',c.name);});toast('Customer archived.');},'Archive customer');break;}
case'toggle-user':{permitted(ui.role,'user');const u=findScoped(state.users,id,ui.companyId);if(u.role==='admin'&&u.active&&rows('users').filter(x=>x.active&&x.role==='admin').length<=1)throw Error('Keep at least one active company admin.');mutate(s=>{findScoped(s.users,id,ui.companyId).active=!u.active;audit(s,u.active?'Staff profile disabled':'Staff profile enabled',u.name);});toast('Demo staff status updated.');break;}
case'add-cart':{permitted(ui.role,'sale');const p=findScoped(state.products,id,ui.companyId),line=ui.cart.find(l=>l.productId===id&&!l.free);const next=structuredClone(ui.cart);if(line)next[ui.cart.indexOf(line)].qty++;else next.push({productId:id,qty:1,free:false});calculateCart(next,state.products,ui.companyId,ui.discountBps,settings().taxBps||0);ui.cart=next;ui.cash='';render();break;}
case'cart-plus':case'cart-minus':{if(!ui.cart[index])break;const next=structuredClone(ui.cart);next[index].qty+=action==='cart-plus'?1:-1;if(next[index].qty<1)next.splice(index,1);calculateCart(next,state.products,ui.companyId,ui.discountBps,settings().taxBps||0);ui.cart=next;ui.cash='';render();break;}
case'cart-remove':ui.cart.splice(index,1);ui.cash='';render();break;
case'cart-free':permitted(ui.role,'free');if(ui.cart[index])ui.cart[index].free=!ui.cart[index].free;ui.cash='';render();break;
case'payment-method':if(['cash','card','bank','credit'].includes(el.dataset.method)){ui.method=el.dataset.method;render();}break;
case'clear-cart':if(ui.cart.length)confirmAction('Clear current order?','All items will be removed from this cart.',()=>{resetCart();render();},'Clear cart');break;
case'checkout':{const tendered=document.getElementById('cash-received')?.value||'0';const result=commitSale(state,ctx(),{lines:ui.cart,discountBps:ui.discountBps,customerId:ui.customerId,method:ui.method,tendered,idempotencyKey:ui.txId});save(result.state);resetCart();render();receipt(result.sale.id);toast('Sale completed. Stock and payment recorded.');break;}
case'hold-cart':{permitted(ui.role,'sale');if(!ui.cart.length)throw Error('Add a product first.');mutate(s=>{s.heldCarts.push({id:makeId(),companyId:ui.companyId,lines:structuredClone(ui.cart),discountBps:ui.discountBps,customerId:ui.customerId,createdAt:new Date().toISOString()});});resetCart();render();toast('Cart held for later.');break;}
case'held-carts':openDialog('Held orders','Resume a cart when your customer is ready.',rows('heldCarts').map(c=>`<div class="stock-item"><div><div class="item-title">${c.lines.reduce((a,l)=>a+l.qty,0)} items · ${e(dateTime(c.createdAt))}</div><div class="item-sub">Stock is checked again before checkout</div></div><button type="button" class="btn btn-small" data-action="resume-cart" data-id="${e(c.id)}">Resume</button></div>`).join('')||empty('No held carts','Hold an order from the checkout screen.'));break;
case'resume-cart':{if(ui.cart.length)throw Error('Clear or hold your current cart first.');const c=findScoped(state.heldCarts,id,ui.companyId);if(c.discountBps)permitted(ui.role,'discount');if(c.lines.some(l=>l.free))permitted(ui.role,'free');ui.cart=structuredClone(c.lines);ui.discountBps=c.discountBps;ui.customerId=c.customerId;ui.txId=makeId();mutate(s=>s.heldCarts=s.heldCarts.filter(x=>x.id!==id));closeDialog();nav('pos');toast('Held cart resumed.');break;}
case'receipt':receipt(id);break;
case'refund':{permitted(ui.role,'refund');const s=findScoped(state.sales,id,ui.companyId);ui.dialog={type:'refund',id};openDialog('Return the full sale',s.number,form('refund-form',field('Reason for return','reason','','text','required maxlength="160"',true)+`<div class="field full"><label><input type="checkbox" name="resellable" required> All sold and free items have been returned and are resellable.</label><small>Every item will be added back to stock. Damaged or partial returns need the production backend workflow.</small></div>`,'Confirm full refund',`Refund total: ${money(s.total)}. Credit sales reverse the customer’s outstanding balance.`));break;}
case'print':{const d=document.getElementById('dialog');d.classList.add('printing');window.print();break;}
case'print-labels':{const products=rows('products').filter(p=>ui.selected.has(p.id)&&p.active);if(!products.length)throw Error('Select at least one label.');openDialog('Print barcode labels',`${products.length} labels · use 100% printer scale.`,`<div class="barcode-sheet">${products.map(barcodeLabel).join('')}</div><p class="print-note no-print">Use a label printer or A4 sheet. Hardware testing is required before live use.</p><div class="form-actions no-print"><button type="button" class="btn btn-primary" data-action="print">${icon('print',14)} Print labels</button></div>`,true);break;}
case'select-labels':rows('products').filter(p=>p.active&&`${p.name} ${p.sku} ${p.barcode}`.toLowerCase().includes(ui.search.toLowerCase())).forEach(p=>ui.selected.add(p.id));render();break;case'clear-labels':ui.selected.clear();render();break;
case'customer-history':{const c=findScoped(state.customers,id,ui.companyId);openDialog(c.name,'Customer purchase history',`<div class="summary-line"><span>Outstanding balance</span><strong>${money(c.balance)}</strong></div>${c.balance&&['admin','manager'].includes(ui.role)?`<button type="button" class="btn btn-small btn-primary bottom-space" data-action="collect-customer" data-id="${e(c.id)}">Record payment</button>`:''}${salesTable(rows('sales').filter(s=>s.customerId===id))}`,true);break;}
case'collect-customer':{permitted(ui.role,'refund');const c=findScoped(state.customers,id,ui.companyId);ui.dialog={type:'collection',id};openDialog('Record customer payment',c.name,form('collection-form',field('Payment received (Rs.)','amount',amountInput(c.balance),'text','required inputmode="decimal"',true),'Record payment',`Outstanding: ${money(c.balance)}. This records collection only; it does not create new sales revenue.`));break;}
case'add-expense':permitted(ui.role,'expense');ui.dialog={type:'expense'};openDialog('Record an expense','Keep operating costs visible.',form('expense-form',field('Description','description','','text','required maxlength="120"',true)+field('Amount (Rs.)','amount','','text','required inputmode="decimal"',true),'Record expense'));break;
case'clear-dates':ui.dateStart='';ui.dateEnd='';render();break;
case'new-license':{permitted(ui.role,'company');const key=licenseKey(),c=state.companies.find(c=>c.id===id);if(!c)throw Error('Company not found.');mutate(s=>{s.licenses.filter(l=>l.companyId===id&&l.status==='active').forEach(l=>l.status='revoked');s.licenses.unshift({id:makeId(),companyId:id,key,status:'active',devices:0,createdAt:new Date().toISOString(),expires:c.expires});audit(s,'Demo license issued',c.name,true);});ui.dialog={type:'key',key};openDialog('Demo key created',c.name,`<div class="created-key">${e(key)}</div><p class="form-intro">This is a local preview key. It cannot activate a real installed device.</p><div class="form-actions"><button type="button" class="btn btn-primary" data-action="copy-key">${icon('copy',14)} Copy key</button></div>`);break;}
case'copy-key':{const key=ui.dialog?.key;if(key&&navigator.clipboard?.writeText){navigator.clipboard.writeText(key).then(()=>toast('Demo key copied.')).catch(()=>toast('Select and copy the key manually.','error'));}else toast('Select and copy the key manually.');break;}
case'revoke-license':permitted(ui.role,'company');confirmAction('Revoke demo key?','Local activation with this key will be disabled.',()=>{mutate(s=>{const l=s.licenses.find(l=>l.id===id);if(!l)throw Error('License not found.');l.status='revoked';audit(s,'Demo license revoked',l.key,true);});toast('Demo key revoked.');},'Revoke key');break;
case'toggle-company':{permitted(ui.role,'company');const c=state.companies.find(c=>c.id===id);if(!c)throw Error('Company not found.');confirmAction(c.status==='active'?'Suspend company?':'Resume company?',`${c.name}: local sales will ${c.status==='active'?'be blocked':'be enabled'}. Records remain available.`,()=>{mutate(s=>{s.companies.find(x=>x.id===id).status=c.status==='active'?'suspended':'active';audit(s,'Company status changed',c.name,true);});toast('Demo company status updated.');});break;}
case'renew-company':{permitted(ui.role,'company');const c=state.companies.find(c=>c.id===id);ui.dialog={type:'renew',id};openDialog('Renew company license',c.name,form('renew-form',field('New expiry date','expires',c.expires,'date','required',true),'Save renewal'));break;}
case'export-inventory':exportData('inventory');break;case'export-customers':exportData('customers');break;case'export-sales':exportData('sales');break;case'export-report':exportData('report');break;case'export-audit':exportData('audit');break;
case'dialog-close':closeDialog();break;case'confirm':{const fn=ui.confirm;if(fn){closeDialog();fn();}break;}
case'reset-demo':confirmAction('Restore sample data?','This deletes all local demo changes across every company in this browser.',()=>{state=createSeed();ui.companyId=state.companies[0].id;ui.selected.clear();resetCart();save(state);toast('Sample data restored.');},'Reset demo');break;
case'help':openDialog('Meet Zentro - POS','A calmer way to run your store.',`<div class="about-logo">zentro<span>.</span></div><p class="form-intro">A working frontend evaluation kit with fictional local data. Product and customer editing, sales, free products, stock receiving, full returns, reports, barcode labels and licensing previews are interactive.</p><ol class="help-steps"><li>Use the top-right selector to preview staff roles.</li><li>Switch fictional companies from the sidebar.</li><li>Press F2 to open checkout. Scan into the search box and press Enter.</li><li>Use the included BACKEND_AI_PROMPT.md to implement real accounts and server-backed data.</li></ol><a class="help-email" href="mailto:sajjadhaiderconnect@gmail.com">Developed By Sajjad Haider</a>`);break;
}}catch(err){toast(err.message||'The action could not be completed.','error');}});

document.addEventListener('input',event=>{const el=event.target;if(el.id==='page-search'){ui.search=el.value;render();}if(el.id==='cash-received')ui.cash=el.value;if(el.id==='cart-discount'&&['admin','manager'].includes(ui.role)&&/^\d{1,3}(\.\d{1,2})?$/.test(el.value)){const bps=moneyToMinor(el.value);if(bps<=10000){ui.discountBps=bps;ui.cash='';render();}}});
document.addEventListener('change',event=>{const el=event.target;try{if(el.id==='role-switch'){switchRole(el.value);}else if(el.id==='company-switch'){if(!state.companies.some(c=>c.id===el.value))return;resetCart();ui.companyId=el.value;ui.search='';ui.selected.clear();ui.filter='all';render();}else if(el.id==='cart-customer')ui.customerId=el.value;else if(el.id==='cart-discount'){permitted(ui.role,'discount');const bps=moneyToMinor(el.value);integer(bps,0,10000);ui.discountBps=bps;ui.cash='';render();}else if(el.id==='inventory-filter'||el.id==='sales-filter'){ui.filter=el.value;render();}else if(el.classList.contains('label-checkbox')){el.checked?ui.selected.add(el.dataset.id):ui.selected.delete(el.dataset.id);render();}else if(el.id==='date-start'||el.id==='date-end'){const from=el.id==='date-start'?el.value:ui.dateStart,to=el.id==='date-end'?el.value:ui.dateEnd;if(from&&to&&from>to)throw Error('The start date must be before the end date.');ui.dateStart=from;ui.dateEnd=to;render();}}catch(err){toast(err.message,'error');render();}});
document.addEventListener('keydown',event=>{if(event.key==='F2'&&!document.getElementById('dialog').open){event.preventDefault();if(can(ui.role,'pos')){nav('pos');document.getElementById('page-search')?.focus();}}if(event.key==='Enter'&&event.target.id==='page-search'&&ui.route==='pos'){event.preventDefault();const text=ui.search.trim().toUpperCase(),p=rows('products').find(p=>p.active&&(p.barcode===text||p.sku===text||(p.barcodeAliases||[]).includes(text)));if(p){const line=ui.cart.find(l=>l.productId===p.id&&!l.free),next=structuredClone(ui.cart);if(line)next[ui.cart.indexOf(line)].qty++;else next.push({productId:p.id,qty:1,free:false});try{calculateCart(next,state.products,ui.companyId,ui.discountBps,settings().taxBps||0);ui.cart=next;ui.search='';ui.cash='';render();}catch(err){toast(err.message,'error');}}else toast('No matching product barcode or SKU.','error');}});

document.addEventListener('submit',event=>{event.preventDefault();const formEl=event.target,data=Object.fromEntries(new FormData(formEl)),id=ui.dialog?.id;try{switch(formEl.id){
case'product-form':{permitted(ui.role,'product');const existing=id?findScoped(state.products,id,ui.companyId):null;const product=validateProduct({...data,stock:existing?.stock??data.stock},state.products,ui.companyId,id);mutate(s=>{if(id){const p=findScoped(s.products,id,ui.companyId),aliases=[...(p.barcodeAliases||[])];if(p.barcode!==product.barcode)aliases.push(p.barcode);Object.assign(p,product,{barcodeAliases:[...new Set(aliases)].filter(a=>a!==product.barcode)});}else{s.products.push({...product,id:makeId(),companyId:ui.companyId,barcodeAliases:[],art:({'Personal care':'bottle','Home & living':'jar','Accessories':'bag','Electronics':'headphones','Groceries':'box','Stationery':'book'})[product.category]||'box'});}audit(s,id?'Product updated':'Product created',product.name);});closeDialog();toast('Product saved.');break;}
case'customer-form':{permitted(ui.role,'customer');const name=cleanText(data.name,80),phone=cleanText(data.phone,30);if(!/^[+\d\s()\-]{5,30}$/.test(phone))throw Error('Enter a valid phone number.');if(rows('customers').some(c=>c.id!==id&&c.phone.replace(/\D/g,'')===phone.replace(/\D/g,'')))throw Error('A customer with this phone number already exists.');const city=String(data.city||'').trim().slice(0,60),email=String(data.email||'').trim().slice(0,120);mutate(s=>{if(id)Object.assign(findScoped(s.customers,id,ui.companyId),{name,phone,city,email});else s.customers.push({id:makeId(),companyId:ui.companyId,name,phone,city,email,balance:0,active:true});audit(s,id?'Customer updated':'Customer created',name);});closeDialog();toast('Customer saved.');break;}
case'user-form':{permitted(ui.role,'user');const name=cleanText(data.name,80),email=cleanText(data.email,120),role=data.role;if(!['admin','manager','inventory','cashier'].includes(role))throw Error('Choose a valid company role.');if(rows('users').some(u=>u.id!==id&&u.email.toLowerCase()===email.toLowerCase()))throw Error('This login identifier already exists.');const u=id?findScoped(state.users,id,ui.companyId):null;if(u?.role==='admin'&&u.active&&role!=='admin'&&rows('users').filter(x=>x.active&&x.role==='admin').length<=1)throw Error('Keep at least one active company admin.');if(!id&&rows('users').filter(u=>u.active).length>=company().userLimit)throw Error('The demo plan’s user limit has been reached.');mutate(s=>{if(id)Object.assign(findScoped(s.users,id,ui.companyId),{name,email,role});else s.users.push({id:makeId(),companyId:ui.companyId,name,email,role,active:true});audit(s,id?'Staff profile updated':'Staff profile created',`${name}: ${ROLE_NAMES[role]}`);});closeDialog();toast('Demo staff profile saved.');break;}
case'stock-form':{permitted(ui.role,'stock');const stock=integer(data.stock),reason=cleanText(data.reason,160),p=findScoped(state.products,id,ui.companyId),delta=stock-p.stock;if(!delta)throw Error('The stock count has not changed.');mutate(s=>{findScoped(s.products,id,ui.companyId).stock=stock;s.stockMoves.push({id:makeId(),companyId:ui.companyId,productId:id,qty:delta,reason,reference:'Stock adjustment',user:ctx().user,createdAt:new Date().toISOString()});audit(s,'Stock adjusted',`${p.name}: ${delta>0?'+':''}${delta}. ${reason}`);});closeDialog();toast('Stock adjustment recorded.');break;}
case'purchase-form':{permitted(ui.role,'stock');const p=findScoped(state.products,data.productId,ui.companyId),qty=integer(data.qty,1,100000),cost=moneyToMinor(data.cost),supplier=cleanText(data.supplier,100);if(!p.active)throw Error('Choose an active product.');if(p.stock+qty>1000000)throw Error('Stock would exceed the demo inventory limit.');mutate(s=>{const product=findScoped(s.products,p.id,ui.companyId);product.cost=Math.round((product.stock*product.cost+qty*cost)/(product.stock+qty));product.stock+=qty;const purchase={id:makeId(),companyId:ui.companyId,number:`PO-${String(rows('purchases').length+1).padStart(4,'0')}`,productId:p.id,productName:p.name,qty,cost,total:qty*cost,supplier,createdAt:new Date().toISOString(),user:ctx().user};s.purchases.unshift(purchase);s.stockMoves.push({id:makeId(),companyId:ui.companyId,productId:p.id,qty,reason:'Purchase received',reference:purchase.number,createdAt:purchase.createdAt,user:ctx().user});audit(s,'Purchase received',`${purchase.number}: ${p.name} × ${qty}`);});closeDialog();toast('Purchase recorded and stock updated.');break;}
case'refund-form':{if(!data.resellable)throw Error('Confirm that all items are returned and resellable.');const next=refundSale(state,ctx(),id,cleanText(data.reason,160));save(next);closeDialog();toast('Full refund recorded. All items returned to stock.');break;}
case'collection-form':{permitted(ui.role,'refund');const amount=moneyToMinor(data.amount),c=findScoped(state.customers,id,ui.companyId);if(amount<=0||amount>c.balance)throw Error('Payment must be greater than zero and no more than the outstanding balance.');mutate(s=>{findScoped(s.customers,id,ui.companyId).balance-=amount;audit(s,'Customer payment collected',`${c.name}: ${money(amount)}`);});closeDialog();toast('Payment collected. Customer balance updated.');break;}
case'expense-form':{permitted(ui.role,'expense');const description=cleanText(data.description,120),amount=moneyToMinor(data.amount);if(!amount)throw Error('Expense amount must be greater than zero.');mutate(s=>{s.expenses.unshift({id:makeId(),companyId:ui.companyId,description,amount,user:ctx().user,createdAt:new Date().toISOString()});audit(s,'Expense recorded',`${description}: ${money(amount)}`);});closeDialog();toast('Expense recorded.');break;}
case'company-form':{permitted(ui.role,'company');const name=cleanText(data.name,80),owner=cleanText(data.owner,80),email=cleanText(data.email,120),deviceLimit=integer(data.deviceLimit,1,100),userLimit=integer(data.userLimit,1,1000),expires=cleanText(data.expires,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(expires)||expires<dateKey(new Date()))throw Error('Choose a future expiry date.');if(!['Starter','Professional','Business'].includes(data.plan))throw Error('Choose a valid plan.');const companyId=makeId(),key=licenseKey();mutate(s=>{s.companies.push({id:companyId,name,owner,email,deviceLimit,userLimit,expires,plan:data.plan,status:'active',branches:1});s.settings[companyId]={name,address:'',phone:'',currency:'PKR',taxBps:0,receiptNote:'Thank you for shopping with us!'};s.users.push({id:makeId(),companyId,name:owner,email,role:'admin',active:true});s.licenses.unshift({id:makeId(),companyId,key,status:'active',devices:0,expires,createdAt:new Date().toISOString()});audit(s,'Company created',name,true);});ui.dialog={type:'key',key};openDialog('Company workspace created',name,`<div class="success-panel">Your local demo workspace is ready. It starts with an empty product catalog.</div><hr class="line"><div class="created-key">${e(key)}</div><p class="form-intro">Use this key in “Try activation flow” to preview opening this company. No real admin identity has been verified.</p><div class="form-actions"><button type="button" class="btn btn-primary" data-action="copy-key">Copy demo key</button></div>`);break;}
case'activation-form':{const key=String(data.key||'').trim().toUpperCase(),l=state.licenses.find(l=>l.key.toUpperCase()===key&&l.status==='active');if(!l)throw Error('Demo key not found or revoked.');const c=state.companies.find(c=>c.id===l.companyId);if(!c||c.status!=='active')throw Error('This demo company is suspended.');if(l.expires<dateKey(new Date()))throw Error('This demo key has expired.');ui.companyId=c.id;ui.selected.clear();closeDialog();switchRole('admin');toast('Activation preview complete. No real account was authenticated.');break;}
case'renew-form':{permitted(ui.role,'company');const expires=cleanText(data.expires,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(expires)||expires<dateKey(new Date()))throw Error('Choose a future expiry date.');mutate(s=>{const c=s.companies.find(c=>c.id===id);c.expires=expires;s.licenses.filter(l=>l.companyId===id&&l.status==='active').forEach(l=>l.expires=expires);audit(s,'Company license renewed',`${c.name}: ${expires}`,true);});closeDialog();toast('Demo license renewed.');break;}
case'settings-form':{permitted(ui.role,'settings');if(ui.role!=='admin')throw Error('Company settings require an admin.');const name=cleanText(data.name,80),taxBps=moneyToMinor(data.tax);integer(taxBps,0,3000);const address=String(data.address||'').trim().slice(0,160),phone=String(data.phone||'').trim().slice(0,30),receiptNote=cleanText(data.receiptNote,160);mutate(s=>{Object.assign(s.settings[ui.companyId],{name,address,phone,taxBps,receiptNote});s.companies.find(c=>c.id===ui.companyId).name=name;audit(s,'Store settings updated',name);});toast('Store settings saved.');break;}
}}catch(err){const errorEl=document.getElementById(formEl.id==='settings-form'?'settings-error':'form-error');if(errorEl){errorEl.textContent=err.message||'Please check your input.';errorEl.hidden=false;}else toast(err.message,'error');}});
window.addEventListener('afterprint',()=>document.getElementById('dialog').classList.remove('printing'));
document.getElementById('dialog').addEventListener('close',()=>{ui.dialog=null;ui.confirm=null;});
window.addEventListener('storage',event=>{if(event.key===storageKey){toast('Demo data changed in another tab. Reload before making changes.','error');}});
window.matchMedia('(max-width:700px)').addEventListener('change',()=>{ui.mobile=false;render();});
render();if(loadMessage)toast(loadMessage,'error');
